#[test]
fn fixes_from_4000_match_vanilla() {
    for &(ty, from, to, input, expected) in CASES_FROM_4000 {
        assert_eq!(update(ty, from, to, input), expected, "{ty} {from} -> {to}: {input}");
    }
}
